  using var queueQuery=em.CreateEntityQuery(typeof(CombatDamageObservationQueueComponent));var queue=CombatDamageObservationUtility.EnsureQueue(em,queueQuery);em.GetBuffer<CombatDamageObservationElement>(queue).Clear();var frames=new JArray();bool launched=false,hit=false;for(int tick=1;tick<=6000;tick++){world.SetTime(new TimeData(tick/60d,1f/60));byte phaseAtStart=em.GetComponentData<GroundMissileLauncherStateComponent>(launcher).Phase;bool flightAtStart=em.HasComponent<GroundMissileInFlightComponent>(launcher);var phases=new JArray();foreach(var handle in order){string owner=TypeManager.GetSystemName(world.Unmanaged.GetSystemTypeIndex(handle)).ToString();var before=em.GetComponentData<GroundMissileLauncherStateComponent>(launcher);var pose=new JObject{["owner"]=owner,["phase_before"]=before.Phase,["timer_before_bits"]=Bits(before.Timer),["anchors_before"]=MissileAnchors(em,launcher),["delta_time_bits"]=Bits(world.Time.DeltaTime),["flying_before"]=MissileFlyingValues(em)};if(owner==typeof(GroundMissileRocketTrailSystem).FullName){pose["presentation_only_boundary"]="Renderer trail consumer not invoked; no simulation state mutation";}else UpdateMissileReferenceSystem(world,handle);var after=em.GetComponentData<GroundMissileLauncherStateComponent>(launcher);pose["phase_after"]=after.Phase;pose["timer_after_bits"]=Bits(after.Timer);pose["anchors_after"]=MissileAnchors(em,launcher);pose["projectiles_after"]=MissileProjectileValues(em);pose["flying_after"]=MissileFlyingValues(em);phases.Add(pose);}using var projectiles=em.CreateEntityQuery(typeof(GroundMissileProjectileComponent));using var impacts=em.CreateEntityQuery(typeof(GroundMissileImpactRequestComponent));launched|=em.HasComponent<GroundMissileInFlightComponent>(launcher)||projectiles.CalculateEntityCount()>0;hit|=em.GetComponentData<UnitHealth>(direct).Current<10000;if((name=="prepare-launch-impact"&&((tick>=95&&tick<=125)||(tick>=155&&tick<=165)||(tick>=330&&tick<=337)))||tick<=3||tick%30==0||hit||phaseAtStart